const { api, action, params } = $input.first().json;

const apiConfigs = {
  gmail: {
    base_url: 'https://gmail.googleapis.com/gmail/v1',
    endpoints: {
      list: { method: 'GET', path: '/users/me/messages', query: { maxResults: params.max_results || 20, q: params.query || '' } },
      read: { method: 'GET', path: `/users/me/messages/${params.message_id || '{message_id}'}`, query: { format: params.format || 'full' } },
      send: { method: 'POST', path: '/users/me/messages/send', body: { raw: Buffer.from(`To: ${params.to || ''}\r\nSubject: ${params.subject || ''}\r\nContent-Type: text/html; charset=utf-8\r\n\r\n${params.body || ''}`).toString('base64url') } },
      search: { method: 'GET', path: '/users/me/messages', query: { maxResults: params.max_results || 50, q: params.query || '' } },
      create: { method: 'POST', path: '/users/me/drafts', body: { message: { raw: Buffer.from(`To: ${params.to || ''}\r\nSubject: ${params.subject || ''}\r\nContent-Type: text/html; charset=utf-8\r\n\r\n${params.body || ''}`).toString('base64url') } } }
    }
  },
  calendar: {
    base_url: 'https://www.googleapis.com/calendar/v3',
    endpoints: {
      list: { method: 'GET', path: `/calendars/${encodeURIComponent(params.calendar_id || 'primary')}/events`, query: { timeMin: params.time_min || new Date().toISOString(), timeMax: params.time_max || new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), maxResults: params.max_results || 50, singleEvents: true, orderBy: 'startTime' } },
      read: { method: 'GET', path: `/calendars/${encodeURIComponent(params.calendar_id || 'primary')}/events/${params.event_id || '{event_id}'}`, query: {} },
      create: { method: 'POST', path: `/calendars/${encodeURIComponent(params.calendar_id || 'primary')}/events`, body: { summary: params.summary || '', description: params.description || '', start: { dateTime: params.start, timeZone: params.timezone || 'UTC' }, end: { dateTime: params.end, timeZone: params.timezone || 'UTC' }, attendees: (params.attendees || []).map(e => ({ email: e })), reminders: { useDefault: true } } },
      search: { method: 'GET', path: `/calendars/${encodeURIComponent(params.calendar_id || 'primary')}/events`, query: { q: params.query || '', timeMin: params.time_min || new Date().toISOString(), maxResults: params.max_results || 50, singleEvents: true, orderBy: 'startTime' } }
    }
  },
  drive: {
    base_url: 'https://www.googleapis.com/drive/v3',
    endpoints: {
      list: { method: 'GET', path: '/files', query: { q: params.folder_id ? `'${params.folder_id}' in parents and trashed = false` : 'trashed = false', pageSize: params.max_results || 100, fields: 'nextPageToken, files(id, name, mimeType, size, modifiedTime, webViewLink, parents)', orderBy: 'modifiedTime desc' } },
      read: { method: 'GET', path: `/files/${params.file_id || '{file_id}'}`, query: { fields: 'id, name, mimeType, size, modifiedTime, webViewLink, description, parents, permissions' } },
      create: { method: 'POST', path: '/files', body: { name: params.name || 'Untitled', mimeType: params.mime_type || 'application/vnd.google-apps.document', parents: params.folder_id ? [params.folder_id] : [], description: params.description || '' } },
      search: { method: 'GET', path: '/files', query: { q: `name contains '${params.query || ''}' and trashed = false`, pageSize: params.max_results || 50, fields: 'nextPageToken, files(id, name, mimeType, size, modifiedTime, webViewLink)', orderBy: 'modifiedTime desc' } }
    }
  },
  sheets: {
    base_url: 'https://sheets.googleapis.com/v4',
    endpoints: {
      list: { method: 'GET', path: `/spreadsheets/${params.spreadsheet_id || '{spreadsheet_id}'}`, query: { fields: 'spreadsheetId,properties.title,sheets.properties' } },
      read: { method: 'GET', path: `/spreadsheets/${params.spreadsheet_id || '{spreadsheet_id}'}/values/${encodeURIComponent(params.range || 'Sheet1')}`, query: { valueRenderOption: params.render_option || 'FORMATTED_VALUE', dateTimeRenderOption: 'FORMATTED_STRING' } },
      create: { method: 'POST', path: '/spreadsheets', body: { properties: { title: params.title || 'New Spreadsheet' }, sheets: [{ properties: { title: params.sheet_name || 'Sheet1' } }] } },
      search: { method: 'GET', path: `/spreadsheets/${params.spreadsheet_id || '{spreadsheet_id}'}/values/${encodeURIComponent(params.range || 'Sheet1')}`, query: { valueRenderOption: 'FORMATTED_VALUE' } },
      send: { method: 'PUT', path: `/spreadsheets/${params.spreadsheet_id || '{spreadsheet_id}'}/values/${encodeURIComponent(params.range || 'Sheet1')}`, query: { valueInputOption: params.input_option || 'USER_ENTERED' }, body: { range: params.range || 'Sheet1', majorDimension: 'ROWS', values: params.values || [] } }
    }
  }
};

const config = apiConfigs[api];
if (!config) {
  return [{ json: { error: true, message: `Unknown Google Suite API: ${api}. Available: ${Object.keys(apiConfigs).join(', ')}` } }];
}

const endpoint = config.endpoints[action];
if (!endpoint) {
  return [{ json: { error: true, message: `Unknown action '${action}' for ${api}. Available: ${Object.keys(config.endpoints).join(', ')}` } }];
}

return [{
  json: {
    method: endpoint.method,
    url: config.base_url + endpoint.path,
    query: endpoint.query || {},
    body: endpoint.body || {},
    api: api,
    action: action
  }
}];

const input = $input.first().json;
const request = $('Build API Request').first().json;

if (input.error || input.statusCode >= 400) {
  return [{
    json: {
      error: true,
      api: request.api,
      action: request.action,
      status_code: input.statusCode || 500,
      message: input.message || input.error || 'API call failed',
      raw_error: input
    }
  }];
}

return [{
  json: {
    success: true,
    api: request.api,
    action: request.action,
    data: input.data || input.body || input,
    metadata: {
      timestamp: new Date().toISOString(),
      execution_id: $execution.id
    }
  }
}];
